 final ConcurrentHashMap<String,AtomicInteger> requests=new ConcurrentHashMap<>();
 final AtomicBoolean loggedIn=new AtomicBoolean();final Set<String> expiryUsed=ConcurrentHashMap.newKeySet();
 Context ctx;volatile String phase="created",scenario="initial",expireOn="";volatile int denialCode,offerDelayMs;volatile boolean formMode,returnHome,scrollMode,nestedScroll,lazyScroll,passiveCaptcha;volatile String lazyDate="";volatile int duringRestriction,lazyDelayMs;volatile boolean visibleMode,canonicalOnScroll;volatile String visibleVariant="valid";volatile int visibleRevision=1,unknownRestriction;volatile String formatMode="";
