 @Override public void onCreate(Bundle args){super.onCreate(args);remoteOnly=args!=null&&"true".equals(args.getString("crossProcess"));current=this;start();}
 @Override public void onStart(){ctx=getTargetContext();baseDate=LocalDate.now(Search.KST).plusDays(2);Bundle result=new Bundle();try{
  checkpoint("probe.start");check(BuildConfig.DEBUG,"debug probe required");check(ctx.checkSelfPermission(android.Manifest.permission.INTERNET)==PackageManager.PERMISSION_DENIED,"probe must not have INTERNET permission");initialDatabases=new HashSet<>(Arrays.asList(ctx.databaseList()));
  if(remoteOnly){runRemoteProcessCoexistence();}else{runVisibleCalendarPhoto();runVisibleLatestHistory();runVisibleSpaLedger();runCanonicalNetworkPreference();runRecognizedFormatFallback();runCanonicalEmptyProof();runVisibleRejections();runUnknownRestriction();runVisiblePauseStop();runRealCollectorCoexistence();assertPrivateValuesExcluded();}check(count("unexpected-document")==0&&count("unexpected-resource")==0,"unexpected fixture-external navigation/resource");
  JSONObject report=progress().put("success",true).put("status","passed").put("phase","probe.complete").put("requestCounts",requestSummary()).put("simulatedLoginClicks",loginClicks).put("webViewPackage",WebView.getCurrentWebViewPackage()==null?"none":WebView.getCurrentWebViewPackage().packageName);save(report);android.util.Log.i("TongDeviceProbe","OFFLINE_DEVICE_PROBE_PASS "+report);result.putString("stream","OFFLINE_DEVICE_PROBE_PASS "+report+"\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){android.util.Log.e("TongDeviceProbe","OFFLINE_DEVICE_PROBE_FAIL phase="+phase,failure);try{save(progress().put("success",false).put("status","failed").put("error",failure.toString()).put("requestCounts",requestSummary()).put("failureContext",failureContext));screenshot("af-visible-failure.png");}catch(Exception ignored){}result.putString("stream","OFFLINE_DEVICE_PROBE_FAIL phase="+phase+" "+failure+"\n");finish(Activity.RESULT_CANCELED,result);}}
 public static final class ProbeAirFranceActivity extends AirFranceActivity {
  @Override void configure(WebView view){super.configure(view);LabInstrumentation probe=current;if(probe==null)throw new AssertionError("missing probe context");probe.wrap(this,view);}
 }
 @Override public Activity newActivity(ClassLoader loader,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{if(name.equals(AirFranceActivity.class.getName()))return new ProbeAirFranceActivity();return super.newActivity(loader,name,intent);}
 @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);String id=a.getIntent().getStringExtra("__af_probe_launch");if(id!=null)resumed.put(id,a);}
 @Override public void callActivityOnDestroy(Activity a){super.callActivityOnDestroy(a);String id=a.getIntent().getStringExtra("__af_probe_launch");if(id!=null)resumed.remove(id,a);}
 JSONObject progress()throws Exception{return new JSONObject().put("appVersion",BuildConfig.VERSION_NAME).put("api",Build.VERSION.SDK_INT).put("networkPermission",false).put("status","running").put("phase",phase).put("cases",cases).put("runtimeMaxHeapBytes",Runtime.getRuntime().maxMemory()).put("evidenceMode",remoteOnly?"production_process_smoke":"debug_main_process_functional").put("remoteEvidence",remoteEvidence);}
 JSONObject requestSummary()throws Exception{JSONObject out=new JSONObject();for(var e:requests.entrySet())out.put(e.getKey(),e.getValue().get());return out;}
 void save(JSONObject value)throws Exception{File tmp=new File(ctx.getFilesDir(),"device-startup-report.tmp");try(OutputStream out=new FileOutputStream(tmp)){out.write(value.toString(2).getBytes(StandardCharsets.UTF_8));}check(tmp.renameTo(new File(ctx.getFilesDir(),"device-startup-report.json")),"report atomic commit failed");}
 void checkpoint(String stage)throws Exception{phase=stage;android.util.Log.i("TongDeviceProbe","DEVICE_STAGE "+stage+" cases="+cases.length());save(progress());}
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 interface Condition{boolean get()throws Exception;}
 void await(String message,long timeout,Condition c)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){if(c.get())return;Thread.sleep(80);}rememberFailureContext();throw new AssertionError(message+" phase="+phase);}
 void rememberFailureContext(){try{onMain(()->{for(Activity item:resumed.values())if(item instanceof AirFranceActivity a&&!a.closed)try{failureContext=new JSONObject().put("nativeState",a.autoState==null?JSONObject.NULL:a.autoState.json()).put("automaticReady",a.automaticReady).put("automaticBusy",a.automaticBusy).put("automaticSaving",a.automaticSaving).put("resumed",a.resumed).put("captureAllowed",a.captureAllowed).put("automaticGeneration",a.automaticGeneration).put("pageGeneration",a.pageGeneration).put("tickScheduled",a.handler.hasCallbacks(a.automaticTick)).put("statusText",a.status==null?"":a.status.getText().toString());}catch(Exception ignored){}});}catch(Throwable ignored){}}
 void onMain(Runnable action){if(Looper.myLooper()==Looper.getMainLooper()){action.run();return;}CountDownLatch latch=new CountDownLatch(1);Throwable[] error={null};new Handler(Looper.getMainLooper()).post(()->{try{action.run();}catch(Throwable f){error[0]=f;}finally{latch.countDown();}});try{check(latch.await(10,TimeUnit.SECONDS),"main callback timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}if(error[0]!=null)throw new AssertionError("main callback failed",error[0]);}
 String eval(WebView view,String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> out=new AtomicReference<>();onMain(()->view.evaluateJavascript(script,v->{out.set(v);latch.countDown();}));check(latch.await(10,TimeUnit.SECONDS),"WebView callback timeout");return out.get();}
 AirFranceActivity launch()throws Exception{String id="af-auto-probe-"+(++launchCounter);onMain(()->ctx.startActivity(new Intent(ctx,AirFranceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK).putExtra("__af_probe_launch",id)));AtomicReference<AirFranceActivity> out=new AtomicReference<>();await("live AF activity did not resume",15000,()->{onMain(()->{Activity candidate=resumed.get(id);if(candidate instanceof AirFranceActivity a&&!a.closed&&!a.isFinishing()&&!a.isChangingConfigurations()&&a.resumed&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())out.set(a);else out.set(null);});return out.get()!=null;});return out.get();}
 void close(AirFranceActivity a)throws Exception{if(!a.closed)onMain(a::finish);await("AF did not close",6000,()->a.closed);check(a.worker.awaitTermination(6,TimeUnit.SECONDS),"AF worker did not close DB");}
 void configurePlan(LocalDate first,int count)throws Exception{JSONObject p=new JSONObject().put("schema",1).put("origin",new JSONObject().put("code","SEL").put("type","CITY")).put("destinations",new JSONArray().put(new JSONObject().put("code","PAR").put("type","CITY"))).put("start",first.toString()).put("end",first.plusDays(count-1).toString()).put("cabin","BUSINESS").put("trip","ROUND_TRIP").put("returnDays",0).put("bothDirections",false);check(ctx.getSharedPreferences("af-auto",Context.MODE_PRIVATE).edit().putString("plan",p.toString()).remove("run").commit(),"test plan could not be persisted");}
 JSONObject state(AirFranceActivity a){AtomicReference<JSONObject> out=new AtomicReference<>();onMain(()->{try{check(a.autoState!=null,"automatic state missing");out.set(a.autoState.json());}catch(Exception e){throw new AssertionError(e);}});return out.get();}
 String url(AirFranceActivity a){AtomicReference<String> out=new AtomicReference<>();onMain(()->out.set(AirFranceActivity.safeUrl(a.browser)));return out.get();}
 int index(AirFranceActivity a){return state(a).optInt("index",-1);}
 int checked(AirFranceActivity a){return state(a).optInt("checked",-1);}
 String mode(AirFranceActivity a){return state(a).optString("mode");}
 int count(String key){return requests.getOrDefault(key,new AtomicInteger()).get();}
 void hit(String key){requests.computeIfAbsent(key,k->new AtomicInteger()).incrementAndGet();}
 int allOffers(){int n=0;for(var e:requests.entrySet())if(e.getKey().startsWith("offer:"))n+=e.getValue().get();return n;}
 long historyCount()throws Exception{try(AirFranceDb db=new AirFranceDb(ctx);android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM history",null)){check(c.moveToFirst(),"history count unavailable");return c.getLong(0);}}
 JSONArray records(LocalDate day)throws Exception{try(AirFranceDb db=new AirFranceDb(ctx)){return db.records("SEL","PAR",YearMonth.from(day));}}
 void assertPrivateValuesExcluded()throws Exception{try(AirFranceDb db=new AirFranceDb(ctx);ByteArrayOutputStream stream=new ByteArrayOutputStream()){db.export(stream);String exported=stream.toString(StandardCharsets.UTF_8.name());check(!exported.contains("OFFLINE_PRIVATE")&&!exported.contains("offline@example.invalid")&&!exported.contains("accessToken")&&!exported.contains("password"),"account/authentication fields leaked to observation history export");}}
 void userLogin(AirFranceActivity a)throws Exception{await("official login page not reached",20000,()->a.browser!=null&&url(a).startsWith(AUTH));check("false".equals(eval(a.browser,"!!window.__tongAF")),"capture object exists on authentication page");await("login control missing",10000,()->"true".equals(eval(a.browser,"!!document.getElementById('fixture-login')")));loginClicks++;eval(a.browser,"document.getElementById('fixture-login').click();true");}
 void waitComplete(AirFranceActivity a,int tasks)throws Exception{await("automatic search did not complete without manual search/import",60000,()->"complete".equals(mode(a)));check(index(a)==tasks&&checked(a)==tasks,"completion counts must follow validated searched tasks");}
 void assertNoCollectors(){onMain(()->check(CollectionService.active==null&&AsianaCollectionService.activeOz==null,"AF automatic workflow affected KE/OZ collectors"));}
