 String visibleText(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView t)s.append(t.getText()).append('\n');if(v instanceof ViewGroup g)for(int i=0;i<g.getChildCount();i++)s.append(visibleText(g.getChildAt(i)));return s.toString();}
 Button button(View v,String text){if(v instanceof Button b&&b.getText().toString().contains(text))return b;if(v instanceof ViewGroup g)for(int i=0;i<g.getChildCount();i++){Button b=button(g.getChildAt(i),text);if(b!=null)return b;}return null;}
 void trace(AirFranceActivity a,WebView v,String what){android.util.Log.i("AFProbe",what+" resumed="+a.resumed+" closed="+a.closed+" captureAllowed="+a.captureAllowed+" current="+AirFranceActivity.safeUrl(v)+" auto="+(a.autoState==null?"null":a.autoState.mode+":"+a.autoState.index+":"+a.autoState.phase));}
