   if("/recaptcha/api2/anchor".equals(path)||"/captcha/challenge".equals(path)){hit("captcha-resource:"+scenario);return response("text/html",200,"<!doctype html><title>Offline synthetic verification frame</title><small>Fixture only</small>");}
   if("/gql/v1".equals(path)&&visibleMode&&u.getQueryParameter("fixtureKind")!=null){String day=u.getQueryParameter("date"),kind=u.getQueryParameter("fixtureKind"),stage=u.getQueryParameter("fixtureStage");hit(kind+":"+day);if("calendar".equals(kind))return response("application/json",200,calendarResponse(day));if("detail".equals(kind)){Thread.sleep(1200);hit("detail-response:"+day);if("offers-empty".equals(formatMode))return response("application/json",200,new JSONObject().put("data",new JSONObject().put("availableOffers",new JSONObject().put("offerItineraries",new JSONArray()))).toString());if("schema".equals(formatMode)||"no-witness".equals(formatMode))return response("application/json",200,"{\"data\":{\"nextVersionOffers\":[]}}");if("hard-route".equals(formatMode)){JSONObject bad=new JSONObject(offerResponse(day));bad.getJSONObject("data").getJSONObject("availableOffers").getJSONArray("offerItineraries").getJSONObject(0).getJSONObject("activeConnection").getJSONArray("segments").getJSONObject(0).put("origin",new JSONObject().put("code","JFK").put("city",new JSONObject().put("code","NYC")));return response("application/json",200,bad.toString());}return response("application/json",200,offerResponse(day));}if("unknown".equals(kind)){int code="scroll".equals(stage)?unknownRestriction:0;hit("unknown-stage:"+day+":"+stage);if("scroll".equals(stage))Thread.sleep(600);return response("application/json",code==403||code==429?code:200,code==403||code==429?"{}":scrollOffers(day,2));}throw new AssertionError("unknown visible fixture request");}
