 JSONObject product(int miles,Integer seats,String family)throws Exception{JSONObject connection=new JSONObject().put("cabinClass","BUSINESS").put("priceInMiles",new JSONObject().put("currency","MILES").put("displayType","FARE_MILES").put("totalPrice",miles)).put("fareFamily",new JSONObject().put("code",family)).put("tax",new JSONObject().put("currencyCode","KRW").put("amount",153000));if(seats!=null)connection.put("numberOfSeatsAvailable",seats);return new JSONObject().put("passengers",new JSONArray().put(new JSONObject().put("type","ADT"))).put("connections",new JSONArray().put(connection));}
